using System;
using LabApi.Events.Arguments.PlayerEvents;
using LabApi.Events.Handlers;
using LabApi.Features;
using LabApi.Loader.Features.Plugins;

namespace WelcomePlugin
{
    public class WelcomePlugin : Plugin
    {
        public override string Name => "WelcomePlugin";
        public override string Description => "Greets players when they join.";
        public override string Author => "You";
        public override Version Version => new Version(1, 0, 0);
        public override Version RequiredApiVersion => new Version(LabApiProperties.CompiledVersion);

        public override void Enable()
        {
            PlayerEvents.Joined += OnJoined;
        }

        public override void Disable()
        {
            PlayerEvents.Joined -= OnJoined;
        }

        private void OnJoined(PlayerJoinedEventArgs ev)
        {
            ev.Player.SendBroadcast($"Welcome to the facility, {ev.Player.Nickname}!", 5);
        }
    }
}

using System;
using System.ComponentModel;
using Exiled.API.Features;
using Exiled.API.Interfaces;
using Exiled.Events.EventArgs.Player;

namespace WelcomePlugin
{
    public class Config : IConfig
    {
        public bool IsEnabled { get; set; } = true;
        public bool Debug { get; set; } = false;

        [Description("Message shown to players when they join. {name} is replaced with their nickname.")]
        public string WelcomeMessage { get; set; } = "Welcome to the facility, {name}!";
    }

    public class WelcomePlugin : Plugin<Config>
    {
        public override string Name => "WelcomePlugin";
        public override string Author => "You";
        public override Version Version => new Version(1, 0, 0);

        public override void OnEnabled()
        {
            Exiled.Events.Handlers.Player.Verified += OnVerified;
            base.OnEnabled();
        }

        public override void OnDisabled()
        {
            Exiled.Events.Handlers.Player.Verified -= OnVerified;
            base.OnDisabled();
        }

        private void OnVerified(VerifiedEventArgs ev)
        {
            ev.Player.Broadcast(5, Config.WelcomeMessage.Replace("{name}", ev.Player.Nickname));
        }
    }
}

using Exiled.Events.EventArgs.Player;
using PlayerRoles;

namespace SpawnItems
{
    public class EventHandlers
    {
        // Subscribe in your plugin's OnEnabled:  Exiled.Events.Handlers.Player.Spawned += handlers.OnSpawned;
        public void OnSpawned(SpawnedEventArgs ev)
        {
            if (ev.Player.Role.Type == RoleTypeId.ClassD)
            {
                ev.Player.AddItem(ItemType.Flashlight);
            }
        }
    }
}

using System;
using CommandSystem;
using Exiled.API.Features;

namespace HealCommand
{
    [CommandHandler(typeof(RemoteAdminCommandHandler))]
    public class HealMe : ICommand
    {
        public string Command => "healme";
        public string[] Aliases => new[] { "hm" };
        public string Description => "Fully heals the player who runs it.";

        public bool Execute(ArraySegment<string> arguments, ICommandSender sender, out string response)
        {
            Player player = Player.Get(sender);
            if (player == null)
            {
                response = "Only players can use this command.";
                return false;
            }

            player.Health = player.MaxHealth;
            response = $"Healed {player.Nickname}.";
            return true;
        }
    }
}
